// Shared constants for the PTY plugin

// PTY terminal and UI constants
export const DEFAULT_TERMINAL_COLS = 120
export const DEFAULT_TERMINAL_ROWS = 40
export const NOTIFICATION_LINE_TRUNCATE = 250
export const NOTIFICATION_TITLE_TRUNCATE = 64

// Default buffer size in characters (approximately 1MB)
const DEFAULT_MAX_BUFFER_SIZE = parseInt(process.env.PTY_MAX_BUFFER_SIZE || '1000000', 10)

export interface SearchMatch {
  lineNumber: number
  text: string
}

export class RingBuffer {
  private buffer: string = ''
  private maxSize: number

  constructor(maxSize: number = DEFAULT_MAX_BUFFER_SIZE) {
    this.maxSize = maxSize
  }

  append(data: string): void {
    this.buffer += data
    if (this.buffer.length > this.maxSize) {
      this.buffer = this.buffer.slice(-this.maxSize)
    }
  }

  private splitBufferLines(): string[] {
    const lines: string[] = this.buffer.split('\n')
    // Remove empty string at end if buffer doesn't end with newline
    if (lines.length && lines[lines.length - 1] === '') {
      lines.pop()
    }
    return lines
  }

  read(offset: number = 0, limit?: number): string[] {
    if (this.buffer === '') return []
    const lines: string[] = this.splitBufferLines()
    const start = Math.max(0, offset)
    const end = limit !== undefined ? start + limit : lines.length
    return lines.slice(start, end)
  }

  readRaw(): string {
    return this.buffer
  }

  search(pattern: RegExp): SearchMatch[] {
    const matches: SearchMatch[] = []
    const lines: string[] = this.splitBufferLines()

    for (let i = 0; i < lines.length; i++) {
      const line = lines[i]
      if (line && pattern.test(line)) {
        matches.push({ lineNumber: i + 1, text: line })
      }
    }
    return matches
  }

  get length(): number {
    if (this.buffer === '') return 0
    const lines = this.splitBufferLines()
    return lines.length
  }

  get byteLength(): number {
    return this.buffer.length
  }

  flush(): void {
    // No-op in new implementation
  }

  clear(): void {
    this.buffer = ''
  }
}

import type { PTYSessionInfo } from './types.ts'

export function formatSessionInfo(session: PTYSessionInfo): string[] {
  const exitInfo = session.exitCode !== undefined ? ` | exit: ${session.exitCode}` : ''
  const exitSignal = session.exitSignal ? ` | signal: ${session.exitSignal}` : ''
  return [
    `[${session.id}] ${session.title}`,
    `  Command: ${session.command} ${session.args.join(' ')}`,
    `  Status: ${session.status}${exitInfo}${exitSignal}`,
    `  PID: ${session.pid}`,
    `  Lines: ${session.lineCount}`,
    `  Workdir: ${session.workdir}`,
    `  Created: ${session.createdAt}`,
    '',
  ]
}

export function formatLine(line: string, lineNum: number, maxLength: number = 2000): string {
  const lineNumStr = lineNum.toString().padStart(5, '0')
  const truncatedLine = line.length > maxLength ? `${line.slice(0, maxLength)}...` : line
  return `${lineNumStr}| ${truncatedLine}`
}

import { accessSync, constants } from 'node:fs'
import { delimiter, join } from 'node:path'
import type { PluginClient } from '../types.ts'
import { RingBuffer } from './buffer.ts'
import { SessionLifecycleManager } from './session-lifecycle.ts'
import type { PTYSession, PTYSessionInfo, ReadResult, SearchResult, SpawnOptions } from './types.ts'

type BuiltinPtyInfo = {
  id: string
  title: string
  command: string
  args: string[]
  cwd: string
  status: 'running' | 'exited'
  pid: number
}

type SessionUpdateCallback = (session: PTYSessionInfo) => void
type RawOutputCallback = (session: PTYSessionInfo, rawData: string) => void

export const sessionUpdateCallbacks: SessionUpdateCallback[] = []
export const rawOutputCallbacks: RawOutputCallback[] = []

export function registerSessionUpdateCallback(callback: SessionUpdateCallback) {
  sessionUpdateCallbacks.push(callback)
}

export function removeSessionUpdateCallback(callback: SessionUpdateCallback) {
  const index = sessionUpdateCallbacks.indexOf(callback)
  if (index !== -1) sessionUpdateCallbacks.splice(index, 1)
}

export function registerRawOutputCallback(callback: RawOutputCallback): void {
  rawOutputCallbacks.push(callback)
}

export function removeRawOutputCallback(callback: RawOutputCallback): void {
  const index = rawOutputCallbacks.indexOf(callback)
  if (index !== -1) rawOutputCallbacks.splice(index, 1)
}

function notifySessionUpdate(session: PTYSessionInfo) {
  for (const callback of sessionUpdateCallbacks) {
    try {
      callback(session)
    } catch {}
  }
}

function notifyRawOutput(session: PTYSessionInfo, rawData: string): void {
  for (const callback of rawOutputCallbacks) {
    try {
      callback(session, rawData)
    } catch {}
  }
}

let _client: PluginClient | null = null
let _directory = process.cwd()
let _httpBase = 'http://127.0.0.1:4096'
let _wsBase = 'ws://127.0.0.1:4096'
let _backendAvailable = true
let _backendLoadError: string | null = null

function normalizeBase(input: URL | string | undefined, protocol: 'http' | 'ws'): string {
  const url = typeof input === 'string' ? new URL(input) : new URL(input?.toString() ?? 'http://127.0.0.1:4096')
  if (url.hostname === '0.0.0.0') url.hostname = '127.0.0.1'
  url.protocol = protocol === 'ws'
    ? (url.protocol === 'https:' ? 'wss:' : 'ws:')
    : (url.protocol === 'wss:' ? 'https:' : 'http:')
  url.pathname = ''
  url.search = ''
  url.hash = ''
  return url.toString().replace(/\/$/, '')
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const res = await fetch(`${_httpBase}${path}`, init)
  if (!res.ok) {
    const body = await res.text().catch(() => '')
    throw new Error(`PTY backend ${init?.method ?? 'GET'} ${path} failed: ${res.status} ${body}`)
  }
  return (await res.json()) as T
}

function markBackendUnavailable(err: unknown): string {
  const message = err instanceof Error ? err.message : String(err)
  _backendAvailable = false
  _backendLoadError = message
  return message
}

function canExecute(path: string): boolean {
  try {
    accessSync(path, constants.X_OK)
    return true
  } catch {
    return false
  }
}

function resolveBackendCommand(command: string, env?: Record<string, string>): string {
  if (!command || command.includes('/')) return command

  const pathValue = env?.PATH ?? process.env.PATH ?? ''
  const fallbackPaths = ['/usr/local/bin', '/usr/bin', '/bin', '/usr/sbin', '/sbin']
  const searchPaths = [...pathValue.split(delimiter), ...fallbackPaths]
  const seen = new Set<string>()

  for (const dir of searchPaths) {
    if (!dir || seen.has(dir)) continue
    seen.add(dir)
    const candidate = join(dir, command)
    if (canExecute(candidate)) return candidate
  }

  return command
}

function escapeXml(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
}

class PTYManager {
  private sessions = new Map<string, PTYSession>()
  private localSessions = new SessionLifecycleManager()

  init(client: PluginClient, serverUrl?: URL, directory?: string): void {
    _client = client
    if (directory) _directory = directory
    _httpBase = normalizeBase(serverUrl, 'http')
    _wsBase = normalizeBase(serverUrl, 'ws')
    _backendAvailable = true
    _backendLoadError = null
  }

  async probe(): Promise<void> {
    try {
      await request<BuiltinPtyInfo[]>('/pty')
      _backendAvailable = true
      _backendLoadError = null
    } catch (err) {
      _backendAvailable = false
      _backendLoadError = err instanceof Error ? err.message : String(err)
    }
  }

  clearAllSessions(): void {
    for (const session of this.sessions.values()) {
      try {
        session.process?.kill?.()
      } catch {}
    }
    this.sessions.clear()
    this.localSessions.clearAllSessions()
  }

  private toInfo(session: PTYSession): PTYSessionInfo {
    return {
      id: session.id,
      title: session.title,
      description: session.description,
      command: session.command,
      args: session.args,
      workdir: session.workdir,
      status: session.status,
      exitCode: session.exitCode,
      exitSignal: session.exitSignal,
      pid: session.pid,
      createdAt: session.createdAt,
      lineCount: session.buffer.length,
    }
  }

  private async sendExitNotification(session: PTYSession): Promise<void> {
    if (!_client || !session.notifyOnExit) return
    const lines = [
      '<pty_exited>',
      `ID: ${session.id}`,
      `Title: ${session.title}`,
      `Exit code: ${session.exitCode ?? 'unknown'}`,
      `Output lines: ${session.buffer.length}`,
      '</pty_exited>',
    ]
    try {
      await _client.session.prompt({
        path: { id: session.parentSessionId },
        body: { noReply: true, parts: [{ type: 'text', text: lines.join('\n') }] },
      })
    } catch {}
  }

  private connectSocket(session: PTYSession): Promise<void> {
    return new Promise((resolve, reject) => {
      const ws = new WebSocket(`${_wsBase}/pty/${session.id}/connect`)
      let settled = false
      const settle = (fn: () => void) => {
        if (settled) return
        settled = true
        fn()
      }

      ws.onopen = () => {
        session.process = {
          pid: session.pid,
          onData: () => {},
          onExit: () => {},
          write: (data: string) => ws.send(data),
          kill: () => ws.close(),
        }
        settle(resolve)
      }

      ws.onmessage = (event) => {
        const text = typeof event.data === 'string' ? event.data : ''
        if (!text) return
        session.buffer.append(text)
        notifyRawOutput(this.toInfo(session), text)
        notifySessionUpdate(this.toInfo(session))
      }

      ws.onclose = async () => {
        session.status = session.status === 'killing' ? 'killed' : 'exited'
        notifySessionUpdate(this.toInfo(session))
        await this.sendExitNotification(session)
      }

      ws.onerror = () => {
        settle(() => reject(new Error(`PTY websocket connection failed for ${session.id}`)))
      }
    })
  }

  private async spawnLocal(opts: SpawnOptions): Promise<PTYSessionInfo> {
    const info = await this.localSessions.spawn(
      opts,
      (session, rawData) => {
        notifyRawOutput(this.localSessions.toInfo(session), rawData)
        notifySessionUpdate(this.localSessions.toInfo(session))
      },
      async (session) => {
        notifySessionUpdate(this.localSessions.toInfo(session))
        await this.sendExitNotification(session)
      },
    )
    notifySessionUpdate(info)
    return info
  }

  async spawn(opts: SpawnOptions): Promise<PTYSessionInfo> {
    if (!_backendAvailable) {
      await this.probe()
    }

    if (!_backendAvailable) {
      return this.spawnLocal(opts)
    }

    const cwd = opts.workdir ?? _directory
    try {
      const created = await request<BuiltinPtyInfo>('/pty', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          command: resolveBackendCommand(opts.command, opts.env),
          args: opts.args ?? [],
          cwd,
          title: opts.title,
          env: opts.env,
        }),
      })

      const session: PTYSession = {
        id: created.id,
        title: created.title,
        description: opts.description,
        command: created.command,
        args: created.args,
        workdir: created.cwd,
        env: opts.env,
        status: created.status,
        pid: created.pid,
        createdAt: new Date().toISOString(),
        parentSessionId: opts.parentSessionId,
        parentAgent: opts.parentAgent,
        notifyOnExit: opts.notifyOnExit ?? false,
        buffer: new RingBuffer(),
        process: null,
      }

      this.sessions.set(session.id, session)
      try {
        await this.connectSocket(session)
      } catch (err) {
        this.sessions.delete(session.id)
        await request(`/pty/${session.id}`, { method: 'DELETE' }).catch(() => undefined)
        throw err
      }
      notifySessionUpdate(this.toInfo(session))
      return this.toInfo(session)
    } catch (err) {
      const message = markBackendUnavailable(err)
      console.warn(`[PTY backend unavailable] spawn fell back to local PTY: ${message}`)
      return this.spawnLocal(opts)
    }
  }

  async write(id: string, data: string): Promise<boolean> {
    const localSession = this.localSessions.getSession(id)
    if (localSession?.process) {
      localSession.process.write(data)
      return true
    }

    const session = this.sessions.get(id)
    if (!session || !session.process) return false
    session.process.write(data)
    return true
  }

  read(id: string, offset: number = 0, limit?: number): ReadResult | null {
    const localSession = this.localSessions.getSession(id)
    if (localSession) {
      const lines = localSession.buffer.read(offset, limit)
      const totalLines = localSession.buffer.length
      return {
        lines,
        totalLines,
        offset,
        hasMore: offset + lines.length < totalLines,
      }
    }

    const session = this.sessions.get(id)
    if (!session) return null
    const lines = session.buffer.read(offset, limit)
    const totalLines = session.buffer.length
    return {
      lines,
      totalLines,
      offset,
      hasMore: offset + lines.length < totalLines,
    }
  }

  search(id: string, pattern: RegExp, offset: number = 0, limit?: number): SearchResult | null {
    const localSession = this.localSessions.getSession(id)
    if (localSession) {
      const matches = localSession.buffer.search(pattern)
      const paged = limit !== undefined ? matches.slice(offset, offset + limit) : matches.slice(offset)
      return {
        matches: paged,
        totalMatches: matches.length,
        totalLines: localSession.buffer.length,
        offset,
        hasMore: offset + paged.length < matches.length,
      }
    }

    const session = this.sessions.get(id)
    if (!session) return null
    const matches = session.buffer.search(pattern)
    const paged = limit !== undefined ? matches.slice(offset, offset + limit) : matches.slice(offset)
    return {
      matches: paged,
      totalMatches: matches.length,
      totalLines: session.buffer.length,
      offset,
      hasMore: offset + paged.length < matches.length,
    }
  }

  async list(): Promise<PTYSessionInfo[]> {
    try {
      if (_backendAvailable) {
        const live = await request<BuiltinPtyInfo[]>('/pty')
        const liveIds = new Set(live.map((item) => item.id))
        for (const item of live) {
          const existing = this.sessions.get(item.id)
          if (existing) {
            existing.title = item.title
            existing.command = item.command
            existing.args = item.args
            existing.workdir = item.cwd
            existing.status = item.status
            existing.pid = item.pid
          } else {
            this.sessions.set(item.id, {
              id: item.id,
              title: item.title,
              command: item.command,
              args: item.args,
              workdir: item.cwd,
              status: item.status,
              pid: item.pid,
              createdAt: new Date().toISOString(),
              parentSessionId: '',
              notifyOnExit: false,
              buffer: new RingBuffer(),
              process: null,
            })
          }
        }
        for (const [id, session] of this.sessions) {
          if (!liveIds.has(id) && session.status === 'running') session.status = 'exited'
        }
      }
    } catch {}
    return [
      ...Array.from(this.sessions.values()).map((session) => this.toInfo(session)),
      ...this.localSessions.listSessions().map((session) => this.localSessions.toInfo(session)),
    ]
  }

  get(id: string): PTYSessionInfo | null {
    const localSession = this.localSessions.getSession(id)
    if (localSession) return this.localSessions.toInfo(localSession)

    const session = this.sessions.get(id)
    return session ? this.toInfo(session) : null
  }

  async kill(id: string, cleanup: boolean = false): Promise<boolean> {
    if (this.localSessions.getSession(id)) {
      return this.localSessions.kill(id, cleanup)
    }

    const session = this.sessions.get(id)
    if (!session) return false
    session.status = 'killing'
    try {
      await request(`/pty/${id}`, { method: 'DELETE' })
    } catch {
      return false
    }
    session.status = 'killed'
    try {
      session.process?.kill?.()
    } catch {}
    if (cleanup) {
      session.buffer.clear()
      this.sessions.delete(id)
    }
    notifySessionUpdate(this.toInfo(session))
    return true
  }

  cleanupBySession(parentSessionId: string): void {
    this.localSessions.cleanupBySession(parentSessionId)
    for (const [id, session] of this.sessions) {
      if (session.parentSessionId === parentSessionId) {
        this.kill(id, true).catch(() => undefined)
      }
    }
  }
}

export const manager = new PTYManager()

export function isBunPtyAvailable(): boolean {
  return _backendAvailable
}

export function bunPtyLoadError(): string | null {
  return _backendLoadError
}

export function initManager(opcClient: OpencodeClient, serverUrl?: URL, directory?: string): void {
  manager.init(opcClient, serverUrl, directory)
  manager.probe().catch(() => undefined)
}

export async function ensurePtyBackendAvailable(): Promise<void> {
  if (_backendAvailable) return
  await manager.probe()
}

export function wrapPtyText(text: string): string {
  return escapeXml(text)
}

import type { PluginClient } from '../types.ts'
import { allStructured } from './wildcard.ts'

type PermissionAction = 'allow' | 'ask' | 'deny'
type BashPermissions = PermissionAction | Record<string, PermissionAction>

interface PermissionConfig {
  bash?: BashPermissions
  external_directory?: PermissionAction
}

let _client: PluginClient | null = null
let _directory: string | null = null

export function initPermissions(client: PluginClient, directory: string): void {
  _client = client
  _directory = directory
}

async function getPermissionConfig(): Promise<PermissionConfig> {
  if (!_client) {
    return {}
  }
  try {
    const response = await _client.config.get()
    if (response.error || !response.data) {
      return {}
    }
    return (response.data as { permission?: PermissionConfig }).permission ?? {}
  } catch {
    return {}
  }
}

async function showToast(
  message: string,
  variant: 'info' | 'success' | 'error' = 'info'
): Promise<void> {
  if (!_client) return
  try {
    await _client.tui.showToast({ body: { message, variant } })
  } catch {
    // Ignore toast errors
  }
}

async function denyWithToast(msg: string, details?: string): Promise<never> {
  await showToast(msg, 'error')
  throw new Error(details ? `${msg} ${details}` : msg)
}

async function handleAskPermission(commandLine: string): Promise<never> {
  await denyWithToast(
    `PTY: Command "${commandLine}" requires permission (treated as denied)`,
    `PTY spawn denied: Command "${commandLine}" requires user permission which is not supported by this plugin. Configure explicit "allow" or "deny" in your opencode.json permission.bash settings.`
  )
  throw new Error('Unreachable') // For TS, should never hit.
}

export async function checkCommandPermission(command: string, args: string[]): Promise<void> {
  const config = await getPermissionConfig()
  const bashPerms = config.bash

  if (!bashPerms) {
    return
  }

  if (typeof bashPerms === 'string') {
    if (bashPerms === 'deny') {
      await denyWithToast('PTY spawn denied: All bash commands are disabled by user configuration.')
    }
    if (bashPerms === 'ask') {
      await handleAskPermission(command)
    }
    return
  }

  const action = allStructured({ head: command, tail: args }, bashPerms)

  if (action === 'deny') {
    await denyWithToast(
      `PTY spawn denied: Command "${command} ${args.join(' ')}" is explicitly denied by user configuration.`
    )
  }

  if (action === 'ask') {
    await handleAskPermission(`${command} ${args.join(' ')}`)
  }
}

export async function checkWorkdirPermission(workdir: string): Promise<void> {
  if (!_directory) {
    return
  }

  const normalizedWorkdir = workdir.replace(/\/$/, '')
  const normalizedProject = _directory.replace(/\/$/, '')

  if (normalizedWorkdir.startsWith(normalizedProject)) {
    return
  }

  const config = await getPermissionConfig()
  const extDirPerm = config.external_directory

  if (extDirPerm === 'deny') {
    await denyWithToast(
      `PTY spawn denied: Working directory "${workdir}" is outside project directory "${_directory}". External directory access is denied by user configuration.`
    )
  }

  if (extDirPerm === 'ask') {
    // TODO: Implement user prompt for external directory access
  }
}

import { RingBuffer } from './buffer.ts'
import type { PTYSession, PTYSessionInfo, SpawnOptions } from './types.ts'
import { DEFAULT_TERMINAL_COLS, DEFAULT_TERMINAL_ROWS } from '../constants.ts'
import { existsSync } from 'node:fs'

// ── Lazy bun-pty import ─────────────────────────────────────────────────────
// bun-pty is a Bun-native module. Static imports crash the whole module graph
// if the native addon isn't available. We lazy-load at first spawn instead.
let _bunPtySpawn: ((...args: any[]) => any) | null = null
let _bunPtyLoadAttempted = false
let _bunPtyError: string | null = null

async function getBunPtySpawn(): Promise<(...args: any[]) => any> {
  if (_bunPtySpawn) return _bunPtySpawn

  if (_bunPtyLoadAttempted) {
    throw new Error(
      `[PTY spawn] bun-pty previously failed to load: ${_bunPtyError}. ` +
        `Cannot spawn PTY sessions. Fix the underlying issue and restart.`
    )
  }

  _bunPtyLoadAttempted = true
  try {
    const mod = await import('bun-pty') as any
    _bunPtySpawn = mod.spawn ?? mod.default?.spawn
    if (!_bunPtySpawn) {
      throw new Error(`bun-pty module loaded but 'spawn' export not found. Exports: ${Object.keys(mod).join(', ')}`)
    }
    return _bunPtySpawn
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err)
    _bunPtyError = msg
    throw new Error(
      `[PTY spawn] Failed to load bun-pty native module.\n` +
        `  Error: ${msg}\n` +
        `  Platform: ${process.platform}/${process.arch}\n` +
        `  Runtime: ${typeof Bun !== 'undefined' ? `Bun ${(Bun as any).version}` : 'NOT Bun (bun-pty requires Bun!)'}\n` +
        `  Fix: cd plugin/opencode-pty && bun install`
    )
  }
}

// ── Session lifecycle ───────────────────────────────────────────────────────
const SESSION_ID_BYTE_LENGTH = 4

function generateId(): string {
  const hex = Array.from(crypto.getRandomValues(new Uint8Array(SESSION_ID_BYTE_LENGTH)))
    .map((b) => b.toString(16).padStart(2, '0'))
    .join('')
  return `pty_${hex}`
}

export class SessionLifecycleManager {
  private sessions: Map<string, PTYSession> = new Map()

  private createSessionObject(opts: SpawnOptions): PTYSession {
    const id = generateId()
    const args = opts.args ?? []
    const workdir = opts.workdir ?? process.cwd()
    const title =
      opts.title ?? (`${opts.command} ${args.join(' ')}`.trim() || `Terminal ${id.slice(-4)}`)

    const buffer = new RingBuffer()
    return {
      id,
      title,
      description: opts.description,
      command: opts.command,
      args,
      workdir,
      env: opts.env,
      status: 'running',
      pid: 0, // will be set after spawn
      createdAt: new Date().toISOString(),
      parentSessionId: opts.parentSessionId,
      parentAgent: opts.parentAgent,
      notifyOnExit: opts.notifyOnExit ?? false,
      buffer,
      process: null, // will be set
    }
  }

  private async spawnProcess(session: PTYSession): Promise<void> {
    // Pre-flight checks with actionable diagnostics
    if (!session.command) {
      throw new Error(`[PTY spawn] command is empty/undefined. Provide a valid command.`)
    }

    if (session.workdir && !existsSync(session.workdir)) {
      throw new Error(
        `[PTY spawn] workdir does not exist: "${session.workdir}". ` +
          `Create the directory first or omit workdir to use cwd.`
      )
    }

    const env = { ...process.env, ...session.env } as Record<string, string>
    const spawnContext = {
      command: session.command,
      args: session.args,
      workdir: session.workdir,
      envKeys: session.env ? Object.keys(session.env) : [],
      cols: DEFAULT_TERMINAL_COLS,
      rows: DEFAULT_TERMINAL_ROWS,
    }

    // Lazy-load bun-pty spawn
    const bunPtySpawn = await getBunPtySpawn()

    try {
      const ptyProcess = bunPtySpawn(session.command, session.args, {
        name: 'xterm-256color',
        cols: DEFAULT_TERMINAL_COLS,
        rows: DEFAULT_TERMINAL_ROWS,
        cwd: session.workdir,
        env,
      })
      session.process = ptyProcess
      session.pid = ptyProcess.pid
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err)
      const stack = err instanceof Error ? err.stack : undefined

      // Classify the error for actionable diagnostics
      let hint = ''
      if (msg.includes('ENOENT') || msg.includes('not found')) {
        hint = `Command "${session.command}" not found. Is it installed and on PATH?`
      } else if (msg.includes('EACCES') || msg.includes('permission')) {
        hint = `Permission denied running "${session.command}". Check file permissions.`
      } else if (msg.includes('EIO') || msg.includes('pty') || msg.includes('openpty')) {
        hint = `PTY allocation failed at OS level. Max PTYs reached? Check: sysctl kern.tty.ptmx_max (macOS) or /proc/sys/kernel/pty/max (Linux).`
      } else if (msg.includes('bun-pty') || msg.includes('native') || msg.includes('dlopen')) {
        hint = `bun-pty native module failed to load. Was it compiled for this platform? Try: cd opencode-pty && bun install`
      }

      const diagnostics = [
        `[PTY spawn FAILED]`,
        `  Error: ${msg}`,
        hint ? `  Hint: ${hint}` : null,
        `  Context: ${JSON.stringify(spawnContext)}`,
        stack ? `  Stack: ${stack.split('\n').slice(0, 5).join('\n    ')}` : null,
      ]
        .filter(Boolean)
        .join('\n')

      console.error(diagnostics)
      throw new Error(diagnostics)
    }
  }

  private setupEventHandlers(
    session: PTYSession,
    onData: (session: PTYSession, data: string) => void,
    onExit: (session: PTYSession, exitCode: number | null) => void
  ): void {
    session.process?.onData((data: string) => {
      session.buffer.append(data)
      onData(session, data)
    })

    session.process?.onExit(({ exitCode, signal }) => {
      // Flush any remaining incomplete line in the buffer
      session.buffer.flush()

      if (session.status === 'killing') {
        session.status = 'killed'
      } else {
        session.status = 'exited'
      }
      session.exitCode = exitCode
      session.exitSignal = signal
      onExit(session, exitCode)
    })
  }

  async spawn(
    opts: SpawnOptions,
    onData: (session: PTYSession, data: string) => void,
    onExit: (session: PTYSession, exitCode: number | null) => void
  ): Promise<PTYSessionInfo> {
    const session = this.createSessionObject(opts)
    await this.spawnProcess(session)
    this.setupEventHandlers(session, onData, onExit)
    this.sessions.set(session.id, session)
    return this.toInfo(session)
  }

  kill(id: string, cleanup: boolean = false): boolean {
    const session = this.sessions.get(id)
    if (!session) {
      return false
    }

    if (session.status === 'running') {
      session.status = 'killing'
      try {
        session.process?.kill()
      } catch {
        // Ignore kill errors
      }
    }

    if (cleanup) {
      session.buffer.clear()
      this.sessions.delete(id)
    }

    return true
  }

  private clearAllSessionsInternal(): void {
    for (const id of [...this.sessions.keys()]) {
      this.kill(id, true)
    }
  }

  clearAllSessions(): void {
    this.clearAllSessionsInternal()
  }

  cleanupBySession(parentSessionId: string): void {
    for (const [id, session] of this.sessions) {
      if (session.parentSessionId === parentSessionId) {
        this.kill(id, true)
      }
    }
  }

  getSession(id: string): PTYSession | null {
    return this.sessions.get(id) || null
  }

  listSessions(): PTYSession[] {
    return Array.from(this.sessions.values())
  }

  toInfo(session: PTYSession): PTYSessionInfo {
    return {
      id: session.id,
      title: session.title,
      description: session.description,
      command: session.command,
      args: session.args,
      workdir: session.workdir,
      status: session.status,
      exitCode: session.exitCode,
      exitSignal: session.exitSignal,
      pid: session.pid,
      createdAt: session.createdAt,
      lineCount: session.buffer.length,
    }
  }
}

export function match(str: string, pattern: string): boolean {
  const regex = new RegExp(
    '^' +
      pattern
        .replace(/[.+^${}()|[\]\\]/g, '\\$&')
        .replace(/\*/g, '.*')
        .replace(/\?/g, '.') +
      '$',
    's'
  )
  return regex.test(str)
}

export function all(input: string, patterns: Record<string, string>): string | undefined {
  const sorted = Object.entries(patterns).sort(
    (a, b) => a[0].length - b[0].length || a[0].localeCompare(b[0])
  )
  let result: string | undefined
  for (const [pattern, value] of sorted) {
    if (match(input, pattern)) {
      result = value
    }
  }
  return result
}

export function allStructured(
  input: { head: string; tail: string[] },
  patterns: Record<string, string>
): string | undefined {
  const sorted = Object.entries(patterns).sort(
    (a, b) => a[0].length - b[0].length || a[0].localeCompare(b[0])
  )
  let result: string | undefined
  for (const [pattern, value] of sorted) {
    const parts = pattern.split(/\s+/)
    const firstPart = parts[0]
    if (!firstPart || !match(input.head, firstPart)) continue
    if (parts.length === 1 || matchSequence(input.tail, parts.slice(1))) {
      result = value
    }
  }
  return result
}

function matchSequence(items: string[], patterns: string[]): boolean {
  if (patterns.length === 0) return true
  const [pattern, ...rest] = patterns
  if (pattern === '*') return matchSequence(items, rest)
  for (let i = 0; i < items.length; i++) {
    const item = items[i]
    if (
      item !== undefined &&
      pattern !== undefined &&
      match(item, pattern) &&
      matchSequence(items.slice(i + 1), rest)
    ) {
      return true
    }
  }
  return false
}

// Shared constants used across the entire application
export const DEFAULT_READ_LIMIT = 500
export const MAX_LINE_LENGTH = 2000
export const DEFAULT_MAX_BUFFER_LINES = 50000

// Performance monitoring constants
export const PERFORMANCE_MEASURE_LIMIT = 100

import { type Plugin, tool } from '../tools/lib/tool'
import { DEFAULT_READ_LIMIT, MAX_LINE_LENGTH } from './opencode-pty/src/shared/constants.ts'
import { formatLine, formatSessionInfo } from './opencode-pty/src/plugin/pty/formatters.ts'
import { initPermissions, checkCommandPermission, checkWorkdirPermission } from './opencode-pty/src/plugin/pty/permissions.ts'
import { initManager, manager } from './opencode-pty/src/plugin/pty/manager.ts'

const ETX = String.fromCharCode(3)
const EOT = String.fromCharCode(4)

function notFound(id: string): Error {
  return new Error(`PTY session '${id}' not found. Use pty_list to see active sessions.`)
}

function parseEscapeSequences(input: string): string {
  return input.replace(/\\(x[0-9A-Fa-f]{2}|u[0-9A-Fa-f]{4}|[nrt\\])/g, (match, seq: string) => {
    if (seq.startsWith('x')) return String.fromCharCode(parseInt(seq.slice(1), 16))
    if (seq.startsWith('u')) return String.fromCharCode(parseInt(seq.slice(1), 16))
    switch (seq) {
      case 'n': return '\n'
      case 'r': return '\r'
      case 't': return '\t'
      case '\\': return '\\'
      default: return match
    }
  })
}

function extractCommands(data: string): string[] {
  return data
    .split(/[\n\r]+/)
    .map((line) => line.trim())
    .filter((line) => line && !line.startsWith(ETX) && !line.startsWith(EOT))
}

function parseCommand(commandLine: string): { command: string; args: string[] } {
  const parts = commandLine.split(/\s+/).filter(Boolean)
  return { command: parts[0] ?? '', args: parts.slice(1) }
}

function validateRegex(pattern: string): boolean {
  try {
    new RegExp(pattern)
    const dangerousPatterns = [
      /\(\?:.*\)\*.*\(\?:.*\)\*/,
      /.*\(\.\*\?\)\{2,\}.*/,
      /.*\(.*\|.*\)\{3,\}.*/,
    ]
    return !dangerousPatterns.some((dangerous) => dangerous.test(pattern))
  } catch {
    return false
  }
}

function buildPtyOutput(
  id: string,
  status: string,
  lines: string[],
  footer: string,
  pattern?: string,
): string {
  const inner = [
    `<pty_output id="${id}" status="${status}"${pattern ? ` pattern="${pattern}"` : ''}>`,
    ...lines,
    '',
    footer,
    `</pty_output>`,
  ].join('\n')
  return `<kortix_system type="pty-output" source="opencode-pty">\n${inner}\n</kortix_system>`
}

function escapeXml(text: string): string {
  return text
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
}

function errorMessage(err: unknown): string {
  return err instanceof Error ? err.message : String(err)
}

function buildPtyFailure(type: string, err: unknown): string {
  const message = escapeXml(errorMessage(err))
  return `<kortix_system type="${type}" source="opencode-pty">\n<pty_failed>\n${message}\n</pty_failed>\n</kortix_system>`
}

async function recoverPtyTool(type: string, action: () => Promise<string>): Promise<string> {
  try {
    return await action()
  } catch (err) {
    console.warn(`[pty-tools] ${type} failed: ${errorMessage(err)}`)
    return buildPtyFailure(type, err)
  }
}

const PtyToolsPlugin: Plugin = async ({ client, directory, serverUrl }) => {
  console.log('[pty-tools] plugin init')
  initPermissions(client, directory)
  initManager(client, serverUrl, directory)
  manager.probe().catch(() => undefined)

  return {
    tool: {
      pty_spawn: tool({
        description: 'Spawn a background PTY session for a long-running or interactive command.',
        args: {
          command: tool.schema.string().describe('Command/executable to run'),
          args: tool.schema.array(tool.schema.string()).optional().describe('Arguments to pass to the command'),
          workdir: tool.schema.string().optional().describe('Working directory for the PTY session'),
          env: tool.schema.object({}).catchall(tool.schema.string()).optional().describe('Additional environment variables'),
          title: tool.schema.string().optional().describe('Human-readable title for the session'),
          description: tool.schema.string().describe('Clear, concise 5-10 word description'),
          notifyOnExit: tool.schema.boolean().optional().describe('Notify when the process exits'),
        },
        async execute(args, ctx) {
          return recoverPtyTool('pty-spawn', async () => {
            await checkCommandPermission(args.command, args.args ?? [])
            if (args.workdir) await checkWorkdirPermission(args.workdir)
            const info = await manager.spawn({
              command: args.command,
              args: args.args,
              workdir: args.workdir,
              env: args.env,
              title: args.title,
              description: args.description,
              parentSessionId: ctx.sessionID,
              parentAgent: ctx.agent,
              notifyOnExit: args.notifyOnExit,
            })
            const inner = [
              'ID: ' + info.id,
              'Title: ' + info.title,
              `Command: ${info.command} ${info.args.join(' ')}`,
              'Workdir: ' + info.workdir,
              'PID: ' + info.pid,
              'Status: ' + info.status,
            ].join('\n')
            return `<kortix_system type="pty-spawn" source="opencode-pty">\n<pty_spawned>\n${inner}\n</pty_spawned>\n</kortix_system>`
          })
        },
      }),

      pty_write: tool({
        description: 'Send input to a running PTY session.',
        args: {
          id: tool.schema.string().describe('PTY session ID'),
          data: tool.schema.string().describe('Input data to send to the PTY'),
        },
        async execute(args) {
          return recoverPtyTool('pty-write', async () => {
            const session = manager.get(args.id)
            if (!session) throw notFound(args.id)
            if (session.status !== 'running') {
              throw new Error(`Cannot write to PTY '${args.id}' - session status is '${session.status}'.`)
            }
            const parsedData = parseEscapeSequences(args.data)
            for (const commandLine of extractCommands(parsedData)) {
              const { command, args: cmdArgs } = parseCommand(commandLine)
              if (command) await checkCommandPermission(command, cmdArgs)
            }
            const success = await manager.write(args.id, parsedData)
            if (!success) throw new Error(`Failed to write to PTY '${args.id}'.`)
            const preview = args.data.length > 50 ? `${args.data.slice(0, 50)}...` : args.data
            const displayPreview = preview
              .replace(new RegExp(ETX, 'g'), '^C')
              .replace(new RegExp(EOT, 'g'), '^D')
              .replace(/\n/g, '\\n')
              .replace(/\r/g, '\\r')
            return `<kortix_system type="pty-write" source="opencode-pty">\nSent ${args.data.length} bytes to ${args.id}: "${displayPreview}"\n</kortix_system>`
          })
        },
      }),

      pty_read: tool({
        description: 'Read PTY output with pagination and optional regex filtering.',
        args: {
          id: tool.schema.string().describe('PTY session ID'),
          offset: tool.schema.number().optional().describe('0-based starting line/match offset'),
          limit: tool.schema.number().optional().describe('Maximum number of lines/matches to return'),
          pattern: tool.schema.string().optional().describe('Regex filter applied before pagination'),
          ignoreCase: tool.schema.boolean().optional().describe('Case-insensitive regex matching'),
        },
        async execute(args) {
          return recoverPtyTool('pty-output', async () => {
            const session = manager.get(args.id)
            if (!session) throw notFound(args.id)
            const offset = args.offset ?? 0
            const limit = args.limit ?? DEFAULT_READ_LIMIT

            if (args.pattern) {
              if (!validateRegex(args.pattern)) {
                throw new Error(`Potentially dangerous regex pattern rejected: '${args.pattern}'. Please use a safer pattern.`)
              }
              const regex = new RegExp(args.pattern, args.ignoreCase ? 'i' : '')
              const result = manager.search(args.id, regex, offset, limit)
              if (!result) throw notFound(args.id)
              if (result.matches.length === 0) {
                return `<kortix_system type="pty-output" source="opencode-pty">\n<pty_output id="${args.id}" status="${session.status}" pattern="${args.pattern}">\nNo lines matched the pattern '${args.pattern}'.\nTotal lines in buffer: ${result.totalLines}\n</pty_output>\n</kortix_system>`
              }
              const lines = result.matches.map((match) => formatLine(match.text, match.lineNumber, MAX_LINE_LENGTH))
              const footer = result.hasMore
                ? `(${result.matches.length} of ${result.totalMatches} matches shown. Use offset=${offset + result.matches.length} to see more.)`
                : `(${result.totalMatches} match${result.totalMatches === 1 ? '' : 'es'} from ${result.totalLines} total lines)`
              return buildPtyOutput(args.id, session.status, lines, footer, args.pattern)
            }

            const result = manager.read(args.id, offset, limit)
            if (!result) throw notFound(args.id)
            if (result.lines.length === 0) {
              return `<kortix_system type="pty-output" source="opencode-pty">\n<pty_output id="${args.id}" status="${session.status}">\n(No output available - buffer is empty)\nTotal lines: ${result.totalLines}\n</pty_output>\n</kortix_system>`
            }
            const lines = result.lines.map((line, index) => formatLine(line, result.offset + index + 1, MAX_LINE_LENGTH))
            const footer = result.hasMore
              ? `(Buffer has more lines. Use offset=${result.offset + result.lines.length} to read beyond line ${result.offset + result.lines.length})`
              : `(End of buffer - total ${result.totalLines} lines)`
            return buildPtyOutput(args.id, session.status, lines, footer)
          })
        },
      }),

      pty_list: tool({
        description: 'List active PTY sessions.',
        args: {},
        async execute() {
          return recoverPtyTool('pty-list', async () => {
            const sessions = await manager.list()
            if (sessions.length === 0) {
              return `<kortix_system type="pty-list" source="opencode-pty">\n<pty_list>\nNo active PTY sessions.\n</pty_list>\n</kortix_system>`
            }
            const inner = ['<pty_list>', ...sessions.flatMap((session) => formatSessionInfo(session)), `Total: ${sessions.length} session(s)`, '</pty_list>'].join('\n')
            return `<kortix_system type="pty-list" source="opencode-pty">\n${inner}\n</kortix_system>`
          })
        },
      }),

      pty_kill: tool({
        description: 'Terminate a PTY session and optionally clean it up.',
        args: {
          id: tool.schema.string().describe('PTY session ID'),
          cleanup: tool.schema.boolean().optional().describe('If true, remove the cached session data too'),
        },
        async execute(args) {
          return recoverPtyTool('pty-kill', async () => {
            const session = manager.get(args.id)
            if (!session) throw notFound(args.id)
            const wasRunning = session.status === 'running'
            const cleanup = args.cleanup ?? false
            const success = await manager.kill(args.id, cleanup)
            if (!success) throw new Error(`Failed to kill PTY session '${args.id}'.`)
            const action = wasRunning ? 'Killed' : 'Cleaned up'
            const cleanupNote = cleanup ? ' (session removed)' : ' (session retained for log access)'
            const inner = [
              '<pty_killed>',
              `${action}: ${args.id}${cleanupNote}`,
              `Title: ${session.title}`,
              `Command: ${session.command} ${session.args.join(' ')}`,
              `Final line count: ${session.lineCount}`,
              '</pty_killed>',
            ].join('\n')
            return `<kortix_system type="pty-kill" source="opencode-pty">\n${inner}\n</kortix_system>`
          })
        },
      }),
    },
    event: async ({ event }) => {
      if (event.type === 'session.deleted') manager.cleanupBySession(event.properties.info.id)
    },
  }
}

export default PtyToolsPlugin

import { tool } from "./lib/tool";
import { getEnv, getKortixRouterBase } from "./lib/get-env";

const SERPER_DEFAULT_URL = "https://google.serper.dev";

function getSerperImagesUrl(): string {
  const override = getKortixRouterBase("serper");
  const base = override || SERPER_DEFAULT_URL;
  return `${base.replace(/\/+$/, "")}/images`;
}

interface SerperImage {
  imageUrl: string;
  title?: string;
  link?: string;
  imageWidth?: number;
  imageHeight?: number;
}

interface SerperResponse {
  images?: SerperImage[];
  searchParameters?: Record<string, unknown>;
}

interface ImageResult {
  url: string;
  title: string;
  source: string;
  width: number;
  height: number;
}

function extractImages(data: SerperResponse): ImageResult[] {
  return (data.images ?? []).map((img) => ({
    url: img.imageUrl,
    title: img.title ?? "",
    source: img.link ?? "",
    width: img.imageWidth ?? 0,
    height: img.imageHeight ?? 0,
  }));
}

export default tool({
  description:
    "Search for images using the Serper Google Images API. " +
    "Returns image URLs with titles, source pages, and dimensions. " +
    "Supports batch queries separated by |||. " +
    "Use specific descriptive queries including topic/brand names for best results.",
  args: {
    query: tool.schema
      .string()
      .describe(
        "Image search query. For batch, separate with ||| (e.g. 'cats ||| dogs')",
      ),
    num_results: tool.schema
      .number()
      .optional()
      .describe("Images per query (1-100). Default: 12"),
  },
  async execute(args, _context) {
    const serperUrlOverride = getKortixRouterBase("serper") ?? undefined;
    // Route through the Kortix router (derived from KORTIX_API_URL); auth with
    // KORTIX_SANDBOX_TOKEN (KORTIX_TOKEN kept as a legacy fallback). Fall back
    // to a raw SERPER_API_KEY only when unset.
    const apiKey = serperUrlOverride
      ? getEnv("KORTIX_SANDBOX_TOKEN") || getEnv("KORTIX_TOKEN")
      : getEnv("SERPER_API_KEY");
    if (!apiKey) return serperUrlOverride
      ? "Error: KORTIX_SANDBOX_TOKEN not set."
      : "Error: SERPER_API_KEY not set.";

    const numResults = Math.max(1, Math.min(args.num_results ?? 12, 100));
    const queries = args.query
      .split("|||")
      .map((q) => q.trim())
      .filter(Boolean);
    if (queries.length === 0) return "Error: empty query.";

    const headers = {
      "X-API-KEY": apiKey,
      "Content-Type": "application/json",
    };

    try {
      if (queries.length === 1) {
        const res = await fetch(getSerperImagesUrl(), {
          method: "POST",
          headers,
          body: JSON.stringify({ q: queries[0], num: numResults }),
        });
        if (!res.ok)
          return `Error: Serper API returned ${res.status}: ${await res.text()}`;

        const data = (await res.json()) as SerperResponse;
        const images = extractImages(data);

        if (images.length === 0) return `No images found for: '${queries[0]}'`;

        return JSON.stringify(
          { query: queries[0], total: images.length, images },
          null,
          2,
        );
      }

      const payload = queries.map((q) => ({ q, num: numResults }));
      const res = await fetch(getSerperImagesUrl(), {
        method: "POST",
        headers,
        body: JSON.stringify(payload),
      });
      if (!res.ok)
        return `Error: Serper API returned ${res.status}: ${await res.text()}`;

      const data = await res.json();
      const dataArr: SerperResponse[] = Array.isArray(data) ? data : [data];

      const results = await Promise.all(
        dataArr.map(async (d, i) => {
          const images = extractImages(d);
          return { query: queries[i], total: images.length, images };
        }),
      );

      return JSON.stringify({ batch_mode: true, results }, null, 2);
    } catch (e) {
      return `Error: ${String(e)}`;
    }
  },
});

import { readFileSync, existsSync, statSync } from "fs";
import { resolve, dirname } from "path";

const S6_ENV_DIR =
  process.env.S6_ENV_DIR || "/run/s6/container_environment";

function liveEnvFiles(): string[] {
  return [
    process.env.KORTIX_AGENT_ENV_FILE,
    "/dev/shm/kortix/agent-env.sh",
    "/tmp/pt-env",
    "/etc/pt-env",
  ].filter((path): path is string => !!path);
}

/**
 * Parsed .env file cache.
 * Loaded once on first miss, never re-read (process lifetime).
 */
let dotenvCache: Record<string, string> | null = null;

/**
 * Parsed live env file cache.
 * Invalidated by mtime so live session env swaps become visible without
 * restarting the OpenCode process that runs these tools.
 */
let liveEnvCache: Record<
  string,
  { mtimeMs: number; env: Record<string, string> }
> = {};

/**
 * Walk up from multiple starting points to find the nearest .env file.
 * Tries both __dirname-based path and process.cwd() to handle bundled
 * and native execution contexts.
 */
function findDotenvPath(): string | null {
  // Try multiple starting points — __dirname may differ when bundled
  const startDirs = [
    dirname(dirname(__dirname)),  // tools/lib/ → tools/ → OpenCode config dir
    process.cwd(),                // wherever OpenCode was started from
  ];

  for (const start of startDirs) {
    let dir = start;
    for (let i = 0; i < 5; i++) {
      const candidate = resolve(dir, ".env");
      if (existsSync(candidate)) return candidate;
      const parent = dirname(dir);
      if (parent === dir) break; // filesystem root
      dir = parent;
    }
  }
  return null;
}

/**
 * Parse a .env file into a key→value map.
 * Supports KEY=VALUE, ignores comments (#) and blank lines.
 * Does NOT handle multi-line values or quoted values with newlines.
 */
function parseDotenv(path: string): Record<string, string> {
  const result: Record<string, string> = {};
  try {
    const content = readFileSync(path, "utf-8");
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) continue;
      const eqIdx = trimmed.indexOf("=");
      if (eqIdx <= 0) continue;
      const key = trimmed.slice(0, eqIdx).trim();
      let value = trimmed.slice(eqIdx + 1).trim();
      // Strip surrounding quotes if present
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      if (key && value) result[key] = value;
    }
  } catch {
    // File unreadable — return empty
  }
  return result;
}

function unquoteEnvValue(value: string): string {
  if (value.startsWith("'") && value.endsWith("'")) {
    return value.slice(1, -1).replace(/'\\''/g, "'");
  }
  if (value.startsWith('"') && value.endsWith('"')) {
    return value
      .slice(1, -1)
      .replace(/\\(["\\$`])/g, "$1")
      .replace(/\\n/g, "\n");
  }
  return value;
}

/**
 * Parse a sourced shell env file (`export KEY='value'`) or plain KEY=VALUE file.
 */
function parseLiveEnvFile(path: string): Record<string, string> {
  const result: Record<string, string> = {};
  try {
    const content = readFileSync(path, "utf-8");
    for (const line of content.split("\n")) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#") || trimmed.startsWith("unset ")) {
        continue;
      }
      const body = trimmed.startsWith("export ")
        ? trimmed.slice("export ".length).trim()
        : trimmed;
      const eqIdx = body.indexOf("=");
      if (eqIdx <= 0) continue;
      const key = body.slice(0, eqIdx).trim();
      const value = unquoteEnvValue(body.slice(eqIdx + 1).trim());
      if (key && value) result[key] = value;
    }
  } catch {
    // File unreadable — return empty
  }
  return result;
}

function getLiveEnvValue(key: string): string | undefined {
  for (const path of liveEnvFiles()) {
    try {
      const stat = existsSync(path) ? statSync(path) : null;
      if (!stat) continue;
      const cached = liveEnvCache[path];
      const env =
        cached && cached.mtimeMs === stat.mtimeMs
          ? cached.env
          : parseLiveEnvFile(path);
      liveEnvCache[path] = { mtimeMs: stat.mtimeMs, env };
      if (env[key]) return env[key];
    } catch {
      // Try the next live env file.
    }
  }
  return undefined;
}

/**
 * Load the .env cache (once per process).
 */
function getDotenv(): Record<string, string> {
  if (dotenvCache !== null) return dotenvCache;
  const path = findDotenvPath();
  dotenvCache = path ? parseDotenv(path) : {};
  return dotenvCache;
}

/**
 * Read an environment variable with multi-tier fallback.
 *
 * Resolution order (first non-empty wins):
 *
 * 1. s6 env dir file     — `/run/s6/container_environment/{key}` (always fresh, ~1μs tmpfs read)
 * 2. `process.env[key]`  — Docker env, manually exported (native dev without s6)
 * 3. live agent env file — `/dev/shm/kortix/agent-env.sh` or warm-claim env files
 * 4. `.env` file          — nearest `.env` walking up from the OpenCode config dir (native dev fallback)
 *
 * s6 is checked first so that env var updates from the secrets manager
 * (kortix-master /env API) take effect immediately — no service restart needed.
 * In native dev (no s6 dir), the read throws and falls through to process.env.
 */
export function getEnv(key: string): string | undefined {
  // 1. s6 env dir — authoritative in containers, always fresh from disk.
  //    kortix-master writes here on every /env POST, so values update without restart.
  //    tmpfs read is ~1μs — negligible cost for always-correct values.
  try {
    const val = readFileSync(`${S6_ENV_DIR}/${key}`, "utf-8").trim();
    if (val) return val;
  } catch {
    // File doesn't exist — not in a container, or key not set via s6.
  }

  // 2. process.env — Docker env vars, shell exports (native dev without s6)
  const fromEnv = process.env[key];
  if (fromEnv) return fromEnv;

  // 3. Live agent env file — warm/hot-swapped OpenCode may keep an old process
  //    env while shells already receive the current session env through BASH_ENV.
  const liveVal = getLiveEnvValue(key);
  if (liveVal) return liveVal;

  // 4. .env file fallback (native dev on macOS — no Docker, no s6)
  const dotenv = getDotenv();
  const envVal = dotenv[key];
  if (envVal) return envVal;

  return undefined;
}

/**
 * Base URL for a Kortix router-proxied upstream service, derived from
 * KORTIX_API_URL. The sandbox only ever holds KORTIX_API_URL + KORTIX_TOKEN;
 * tools build their proxy endpoint from those two. Normalizes so it works
 * whether KORTIX_API_URL is a bare origin or already ends in /v1 or /v1/router.
 * Returns null when KORTIX_API_URL is unset.
 */
export function getKortixRouterBase(service: string): string | null {
  const raw = getEnv("KORTIX_API_URL");
  if (!raw) return null;
  const root = raw
    .replace(/\/+$/, "")
    .replace(/\/v1\/router$/, "")
    .replace(/\/v1$/, "");
  return `${root}/v1/router/${service}`;
}

