## State Machines

```javascript
class StateMachine {
  constructor(owner) {
    this.owner = owner;
    this.states = {};
    this.current = null;
  }

  add(name, state) {
    this.states[name] = state;
    state.machine = this;
    state.owner = this.owner;
  }

  transition(name) {
    if (this.current) this.current.exit();
    this.current = this.states[name];
    this.current.enter();
  }

  update(dt) { if (this.current) this.current.update(dt); }
}
